#include <vector>
#include <queue>
#include <unordered_map>
#include <limits>
#include <cmath>
#include <algorithm>

// Mock Node and Graph classes for testing
struct Node {
    double x = 0.f;
    double y = 0.f;
    float g_value = 0.0f;
    float h_value = std::numeric_limits<float>::max();
    bool visited = false;
    Node* parent = nullptr;
    std::vector<Node*> neighbors;

    float distance(const Node& other) const {
        return std::sqrt(std::pow(x - other.x, 2) + std::pow(y - other.y, 2));
    }
};

struct Graph {
    std::vector<Node> nodes;
    Node& get_node(int idx) { return nodes[idx]; }
};

std::vector<Node> a_star_search(Graph& graph, int start_idx, int end_idx) {
    // Initialize start and end nodes
    Node& start_node = graph.get_node(start_idx);
    Node& end_node = graph.get_node(end_idx);

    // Reset node values
    for (auto& node : graph.nodes) {
        node.g_value = std::numeric_limits<float>::max();
        node.h_value = std::numeric_limits<float>::max();
        node.visited = false;
        node.parent = nullptr;
    }

    // Set start node values
    start_node.g_value = 0.0f;
    start_node.h_value = start_node.distance(end_node);

    // Priority queue: pairs of (f_value, node_index)
    auto compare = [](const std::pair<float, int>& a, const std::pair<float, int>& b) {
        return a.first > b.first;
    };
    std::priority_queue<std::pair<float, int>, std::vector<std::pair<float, int>>, decltype(compare)> open_queue(compare);
    open_queue.push({start_node.g_value + start_node.h_value, start_idx});

    // Track visited nodes
    std::vector<bool> visited(graph.nodes.size(), false);

    while (!open_queue.empty()) {
        // Get the node with the lowest f_value
        auto current = open_queue.top();
        open_queue.pop();
        int current_idx = current.second;
        Node& current_node = graph.get_node(current_idx);

        // Skip if already visited
        if (visited[current_idx]) {
            continue;
        }

        // Mark as visited
        visited[current_idx] = true;

        // Check if we've reached the goal
        if (current_idx == end_idx) {
            // Reconstruct the path
            std::vector<Node> path;
            Node* current = &end_node;
            while (current != nullptr) {
                path.push_back(*current);
                current = current->parent;
            }
            std::reverse(path.begin(), path.end());
            return path;
        }

        // Explore neighbors
        for (Node* neighbor : current_node.neighbors) {
            int neighbor_idx = neighbor - &graph.nodes[0]; // Calculate index

            // Skip if already visited
            if (visited[neighbor_idx]) {
                continue;
            }

            // Calculate tentative g_value
            float tentative_g = current_node.g_value + current_node.distance(*neighbor);

            // Update neighbor if tentative_g is better
            if (tentative_g < neighbor->g_value) {
                neighbor->parent = &current_node;
                neighbor->g_value = tentative_g;
                neighbor->h_value = neighbor->distance(end_node);
                open_queue.push({neighbor->g_value + neighbor->h_value, neighbor_idx});
            }
        }
    }

    // No path found
    return {};
}

